! Typed-handle wrappers, included into the module contains section.

    function rocsolver_get_version_string_cstr(buf, len_) result(get_version_string)
      use, intrinsic :: iso_c_binding
      use hipfort_rocblas_enums
      implicit none
      character(len=*), intent(out) :: buf
      integer(c_size_t), value :: len_
      integer(kind(rocblas_status_success)) :: get_version_string
      character(len=len(buf)+1, kind=c_char), target :: buf__c
      integer :: i__c
      buf__c = repeat(c_null_char, len(buf)+1)
      get_version_string = rocsolver_get_version_string_(c_loc(buf__c), len_)
      buf = ""
      do i__c = 1, len(buf)
        if (buf__c(i__c:i__c) == c_null_char) exit
        buf(i__c:i__c) = buf__c(i__c:i__c)
      end do
    end function rocsolver_get_version_string_cstr

    function rocsolver_set_alg_mode_typed(handle, func, mode) result(set_alg_mode)
      use, intrinsic :: iso_c_binding
      use hipfort_handles
      use hipfort_rocblas_enums
      implicit none
      type(rocblas_handle_t), value :: handle
      integer(kind(rocsolver_function_bdsqr)), value :: func
      integer(kind(rocsolver_alg_mode_gpu)), value :: mode
      integer(kind(rocblas_status_success)) :: set_alg_mode
      set_alg_mode = rocsolver_set_alg_mode_(handle%ptr, func, mode)
    end function rocsolver_set_alg_mode_typed

